from pathlib import Path
import re
j=Path('src/main/java/com/motorrent/motorbikerental');r=Path('src/main/resources')
p=j/'controller/web/CustomerPageController.java';s=p.read_text(encoding='utf-8').replace('public String home(Model model) {','public String home(Model model, @RequestParam(defaultValue="xe-ga") String recommended) {');s=s.replace('model.addAttribute("motorbikes", motorbikeService.getAllMotorbikes());','''if(!List.of("xe-ga","xe-so","xe-con-tay").contains(recommended)) recommended="xe-ga";
        model.addAttribute("recommended",recommended);
        model.addAttribute("motorbikes",motorbikeService.filterMotorbikes("",recommended,null,null,null,"popular").stream().filter(m->!List.of("MAINTENANCE","UNAVAILABLE").contains(m.getStatus())).limit(6).toList());''');p.write_text(s,encoding='utf-8')
p=r/'templates/customer/home.html';s=p.read_text(encoding='utf-8');s=s.replace('<section id="bang-gia-xe" class="customer-workspace"><h2>Đội xe của cửa hàng</h2>','''<section id="bang-gia-xe" class="customer-workspace home-fleet"><div class="cw-row"><div><p class="fleet-eyebrow">KHÁM PHÁ ĐỘI XE</p><h2>Xe đề cử cho chuyến đi</h2></div><a class="cw-btn" href="/customer/motorbike-list">Xem tất cả xe →</a></div><p class="cw-muted">Tối đa 6 xe mỗi loại, ưu tiên đánh giá cao trong danh mục hiện có.</p><nav class="catalog-tabs" aria-label="Loại xe đề cử"><a th:href="@{/(recommended='xe-ga')}+'#bang-gia-xe'" th:classappend="${recommended=='xe-ga'?'active':''}" th:attr="aria-current=${recommended=='xe-ga'?'page':null}">Xe ga</a><a th:href="@{/(recommended='xe-so')}+'#bang-gia-xe'" th:classappend="${recommended=='xe-so'?'active':''}" th:attr="aria-current=${recommended=='xe-so'?'page':null}">Xe số</a><a th:href="@{/(recommended='xe-con-tay')}+'#bang-gia-xe'" th:classappend="${recommended=='xe-con-tay'?'active':''}" th:attr="aria-current=${recommended=='xe-con-tay'?'page':null}">Xe côn tay</a></nav>''');s=s.replace('<div class="cw-grid"><article class="cw-card" th:each="m : ${motorbikes}">','<div class="bike-catalog-grid"><article class="cw-card bike-card" th:each="m : ${motorbikes}">');p.write_text(s,encoding='utf-8')
# Keep live result cards; rebuild the compact search and filter layout requested by owner.
p=r/'templates/customer/motorbike-list.html';s=p.read_text(encoding='utf-8');cards=s[s.index('<div class="cw-grid"><article'):s.index('</main>')].replace('class="cw-grid"','class="bike-catalog-grid"').replace('class="cw-card" th:each','class="cw-card bike-card" th:each')
form='''<!DOCTYPE html><html xmlns:th="http://www.thymeleaf.org" lang="vi"><head th:replace="~{fragments/head :: head(title='Danh sách xe')}"></head><body class="bg-surface text-on-surface"><div th:replace="~{fragments/customer-header :: header(isHome=false)}"></div><main class="customer-workspace catalog-page"><div class="catalog-title"><p class="fleet-eyebrow">MOTORENT ĐÀ NẴNG</p><h1>Chọn xe cho hành trình của bạn</h1><p class="cw-muted">Chọn lịch và điểm nhận xe để kiểm tra danh mục còn trống.</p></div>
<form id="catalog-search" method="get"><div class="catalog-booking"><div class="catalog-booking-fields"><label class="cw-field"><span>◷ NGÀY &amp; GIỜ NHẬN XE</span><input type="datetime-local" name="pickup" th:value="${pickup}"></label><label class="cw-field"><span>◷ NGÀY &amp; GIỜ TRẢ XE</span><input type="datetime-local" name="returnAt" th:value="${returnAt}"></label><label class="cw-field"><span>⌖ ĐỊA ĐIỂM NHẬN XE</span><select id="pickupLocation" name="location"><option value="store" th:selected="${location=='store'}">Nhận xe tại cửa hàng (miễn phí)</option><option value="maps_delivery" th:selected="${location!='store'}">Chọn điểm giao trên bản đồ</option></select></label><button class="cw-btn primary" type="submit">⌕ Kiểm tra xe trống</button></div><div class="catalog-booking-note"><span th:text="${pickup!=null and returnAt!=null ? 'Đã kiểm tra: '+#lists.size(motorbikes)+' xe phù hợp với lịch thuê.' : 'Chọn cả ngày nhận và ngày trả để kiểm tra lịch trống.'}"></span><button type="button" class="catalog-map-link" onclick="openMapModal()">Chọn vị trí giao xe</button></div><p id="currentDeliveryAddressText" class="cw-muted" th:text="${deliveryAddress}"></p></div>
<input id="prefilledAddress" type="hidden" name="deliveryAddress" th:value="${deliveryAddress}"><input id="prefilledLat" type="hidden" name="deliveryLat" th:value="${deliveryLat}"><input id="prefilledLng" type="hidden" name="deliveryLng" th:value="${deliveryLng}">
<div class="catalog-tabs" role="group" aria-label="Loại xe"><button type="submit" name="category" value="all" th:classappend="${category=='all'?'active':''}">Tất cả xe</button><button type="submit" name="category" value="xe-ga" th:classappend="${category=='xe-ga'?'active':''}">Xe ga</button><button type="submit" name="category" value="xe-so" th:classappend="${category=='xe-so'?'active':''}">Xe số</button><button type="submit" name="category" value="xe-con-tay" th:classappend="${category=='xe-con-tay'?'active':''}">Xe côn tay</button><button type="submit" name="category" value="xe-dien" th:classappend="${category=='xe-dien'?'active':''}">Xe điện</button></div>
<div class="catalog-filters"><input name="keyword" th:value="${keyword}" placeholder="Tìm tên xe…" aria-label="Tên xe"><select name="priceFilter" aria-label="Giá thuê"><option value="all">Mức giá: Tất cả</option><option value="under120" th:selected="${priceFilter=='under120'}">Dưới 120.000 ₫</option><option value="120to180" th:selected="${priceFilter=='120to180'}">120.000–180.000 ₫</option><option value="above180" th:selected="${priceFilter=='above180'}">Trên 180.000 ₫</option></select><select name="ccFilter" aria-label="Dung tích"><option value="all">Dung tích: Tất cả</option><option th:each="cc : ${ccOptions}" th:value="${cc}" th:text="${cc+' cc'}" th:selected="${ccFilter==#strings.toString(cc)}"></option></select><select name="statusFilter" aria-label="Trạng thái"><option value="all">Trạng thái: Tất cả</option><option value="available" th:selected="${statusFilter=='available'}">Sẵn sàng</option></select><select name="sortBy" aria-label="Sắp xếp"><option value="popular">Đánh giá cao</option><option value="price-asc" th:selected="${sortBy=='price-asc'}">Giá tăng dần</option><option value="price-desc" th:selected="${sortBy=='price-desc'}">Giá giảm dần</option><option value="newest" th:selected="${sortBy=='newest'}">Đời xe mới</option></select><button class="cw-btn" type="submit">Lọc xe</button></div><input type="hidden" id="current-category" th:value="${category}"></form><p class="cw-muted" th:text="${#lists.size(motorbikes)+' xe phù hợp'}"></p><p class="cw-card" th:if="${#lists.isEmpty(motorbikes)}">Không có xe phù hợp. Hãy thử lịch hoặc bộ lọc khác.</p>'''
s=form+cards+'''</main><div th:replace="~{fragments/map-modal :: mapModal}"></div><div th:replace="~{fragments/customer-footer :: footer}"></div><script src="/js/customer.js" defer></script><script src="/js/catalog.js" defer></script></body></html>''';p.write_text(s,encoding='utf-8')
(r/'static/js/catalog.js').write_text('''(() => {const form=document.getElementById('catalog-search'),pickup=form.elements.pickup,drop=form.elements.returnAt,location=form.elements.location;
location.addEventListener('change',()=>{if(location.value!=='store')openMapModal();else ['prefilledAddress','prefilledLat','prefilledLng'].forEach(id=>document.getElementById(id).value='');});
form.addEventListener('submit',e=>{drop.setCustomValidity('');if(Boolean(pickup.value)!==Boolean(drop.value)||pickup.value&&drop.value<=pickup.value){e.preventDefault();drop.setCustomValidity('Chọn đủ lịch nhận và trả; ngày trả phải sau ngày nhận.');drop.reportValidity();return;}if(e.submitter?.name!=='category'){let field=document.createElement('input');field.type='hidden';field.name='category';field.value=document.getElementById('current-category').value;form.append(field);}if(location.value!=='store'&&!document.getElementById('prefilledLat').value){e.preventDefault();openMapModal();}});
drop.addEventListener('input',()=>drop.setCustomValidity(''));})();''',encoding='utf-8')
with (r/'static/css/customer-workspace.css').open('a',encoding='utf-8') as f:f.write('''
/* Catalog layout: isolated from account and operations forms. */
.bike-catalog-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:22px}.bike-catalog-grid .bike-card{margin:0;padding:18px}.bike-card h2{font-size:18px}.bike-card .cw-facts{flex-wrap:wrap}.catalog-title{text-align:center;margin:30px 0}.fleet-eyebrow{font-size:11px;letter-spacing:2px;color:#e89542;font-weight:800}.catalog-booking{padding:20px;background:#102331;border:1px solid #ffffff12;border-radius:18px}.catalog-booking-fields{display:grid;grid-template-columns:1fr 1fr 1.3fr auto;gap:16px;align-items:end}.catalog-booking .cw-field span{font-size:10px;color:#c0ac94;letter-spacing:.6px}.catalog-booking-note{display:flex;justify-content:space-between;gap:16px;border-top:1px solid #ffffff0c;margin-top:15px;padding-top:12px;font-size:12px;color:#57ba9e}.catalog-map-link{color:#edb17c}.catalog-tabs{display:flex;flex-wrap:wrap;gap:8px;margin:24px 0 20px}.catalog-tabs a,.catalog-tabs button{padding:10px 20px;border:1px solid #ffffff12;border-radius:24px;color:#b6c5d1;background:#142938;font-weight:700;font-size:13px}.catalog-tabs .active{background:#ff850b;color:#20160b;box-shadow:0 4px 18px #f9731620}.catalog-filters{display:flex;flex-wrap:wrap;gap:10px;padding:14px;background:#102331;border-radius:12px;margin-bottom:20px}.catalog-filters input,.catalog-filters select{background:#091b29;color:#e6edf5;border:1px solid #304451;border-radius:8px;padding:10px;font-size:13px;min-width:0}.catalog-filters input{flex:1;min-width:140px}.home-fleet{max-width:1200px;color:#172b3a}.home-fleet>.cw-muted,.home-fleet .cw-row+.cw-muted{color:#506578}.home-fleet .bike-card{color:#e6edf5}.home-fleet>.cw-row{margin-bottom:12px}.home-fleet .catalog-tabs{justify-content:center}.home-fleet h2{font-size:27px}.home-fleet .bike-card h2{font-size:18px}#bang-gia-xe{scroll-margin-top:110px}
@media(max-width:980px){.catalog-booking-fields{grid-template-columns:1fr 1fr}.bike-catalog-grid{gap:14px}.bike-catalog-grid .bike-card{padding:14px}}
@media(max-width:700px){.bike-catalog-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.catalog-booking-fields{grid-template-columns:1fr 1fr}.catalog-booking-note{flex-wrap:wrap}}
@media(max-width:480px){.bike-catalog-grid,.catalog-booking-fields{grid-template-columns:1fr}.catalog-tabs{gap:6px}.catalog-tabs a,.catalog-tabs button{padding:9px 14px}}
''')
